import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.lang.reflect.Array
import java.util.*
import kotlin.system.exitProcess

const val MOD = 1_000_000_007
const val eps = 1e-9
const val INF = 1_000_000_000
const val autoflush = false

fun rep(n: Int) = 0 until n
fun rep(s: Int, t: Int) = s until t
fun req(s: Int, t: Int) = s..t

class MyScanner(private val r: BufferedReader = BufferedReader(InputStreamReader(System.`in`))) {
    private var line: Array<String> = emptyArray()
    private var index = 0

    private fun newLine() {
        if (index >= line.size) {
            line = r.readLine()?.split(" ") ?: emptyArray()
            index = 0
        }
    }

    fun next(): String {
        newLine()
        return line[index++]
    }

    fun nextChar() = next()[0]

    fun nextInt() = next().toInt()

    fun nextLong() = next().toLong()

    fun nextDouble() = next().toDouble()

    fun nextLine(): String {
        line = emptyArray()
        return r.readLine() ?: ""
    }

    fun nextStrings(): Array<String> {
        line = emptyArray()
        return (r.readLine() ?: "").split(" ").toTypedArray()
    }

    fun nextChars() = next().toCharArray()

    fun nextInts(): IntArray {
        return nextStrings().map { it.toInt() }.toIntArray()
    }

    fun nextLongs(): LongArray {
        return nextStrings().map { it.toLong() }.toLongArray()
    }

    fun nextDoubles(): DoubleArray {
        return nextStrings().map { it.toDouble() }.toDoubleArray()
    }

    fun next(n: Int): Array<String> {
        val res = Array<String>(n) { "" }
        for (i in 0 until n) res[i] = next()
        return res
    }

    fun nextInt(n: Int): IntArray {
        val res = IntArray(n)
        for (i in 0 until n) res[i] = nextInt()
        return res
    }

    fun nextLong(n: Int): LongArray {
        val res = LongArray(n)
        for (i in 0 until n) res[i] = nextLong()
        return res
    }

    fun nextDouble(n: Int): DoubleArray {
        val res = DoubleArray(n)
        for (i in 0 until n) res[i] = nextDouble()
        return res
    }

    fun nextStrings(n: Int): Array<Array<String>> {
        val res = Array<Array<String>>(n) { emptyArray() }
        for (i in 0 until n) res[i] = nextStrings()
        return res
    }

    fun nextInts(n: Int): Array<IntArray> {
        val res = Array<IntArray>(n) { emptyArray() }
        for (i in 0 until n) res[i] = nextInts()
        return res
    }

    fun nextLongs(n: Int): Array<LongArray> {
        val res = Array<LongArray>(n) { emptyArray() }
        for (i in 0 until n) res[i] = nextLongs()
        return res
    }

    fun nextDoubles(n: Int): Array<DoubleArray> {
        val res = Array<DoubleArray>(n) { emptyArray() }
        for (i in 0 until n) res[i] = nextDoubles()
        return res
    }
}

class D {
    private var A: IntArray = emptyArray()
    private var N = 0
    private var Q: IntArray = emptyArray()
    private var R: Array<IntArray> = emptyArray()
    private var H: IntArray = emptyArray()

    init {
        val sc = MyScanner()
        N = sc.nextInt()
        A = sc.nextInts()

        if (N == 1) exit(1)

        outer@ for (i in 1 until N) {
            for (j in 0 until i) {
                for (k in 0 until i) {
                    if (A[j] + A[k] == A[i]) continue@outer
                }
            }
            exit(-1)
        }

        val M = TreeMap<Int, Int>()
        for (i in 0 until N) M[A[i]] = i

        Q = IntArray(N)
        R = Array(N) { IntArray(N) }

        for (i in 0 until N) {
            for (j in 0 until i) {
                val diff = A[i] - A[j]
                if (M.containsKey(diff)) {
                    val k = M[diff]!!
                    Q[i] = Q[i] or (1 shl j)
                    R[i][j] = k
                }
            }
        }

        H = IntArray(1 shl (N - 1)) { -1 }

        val res = solve(1, 1)
        require(res <= N)
        exit(res)
    }

    private fun solve(X: Int, J: Int): Int {
        var B = X and Q[J]
        if (B == 0) return H[X] = INF

        for (i in 0 until J) {
            val U = 1 shl i
            val V = 1 shl R[J][i]
            if ((B and U) != 0 && (B and V) != 0) break
            if (i == J - 1) return H[X] = INF
        }

        if (J == N - 1) return H[X] = Integer.bitCount(X)

        val Y = X or (1 shl J)
        var res = INF
        for (j in 0 until J) {
            val W = 1 shl j
            if ((Y and W) != 0) {
                val V = Y and W.inv()
                val Rval = if (H[V] == -1) solve(V, J + 1) else H[V]
                res = minOf(res, Rval)
            }
        }
        val Rval = if (H[Y] == -1) solve(Y, J + 1) else H[Y]
        res = minOf(res, Rval)
        return H[X] = res
    }

    companion object {
        private val pw = PrintWriter(System.out, autoflush)
        private var t = 0L

        @JvmStatic
        fun main(args: Array<String>) {
            start()
            D()
            exit()
        }

        private fun start() {
            t = System.currentTimeMillis()
        }

        private fun millis() = System.currentTimeMillis()

        fun print(vararg o: Any) {
            printDelim(" ", *o)
        }

        fun cprint(vararg o: Any) {
            printDelim("", *o)
        }

        fun printDelim(delim: String, vararg o: Any) {
            pw.println(build(delim, *o))
        }

        fun exit(vararg o: Any) {
            print(*o)
            exit()
        }

        fun exit() {
            pw.close()
            System.out.flush()
            System.err.println("------------------")
            System.err.println("Time: " + ((millis() - t) / 1000.0))
            exitProcess(0)
        }

        fun NO() = throw Error("NO!")

        fun build(delim: String, vararg o: Any): String {
            val b = StringBuilder()
            for (obj in o) append(b, obj, delim)
            return b.toString().trim()
        }

        fun append(b: StringBuilder, o: Any, delim: String) {
            if (o.javaClass.isArray) {
                val len = Array.getLength(o)
                for (i in 0 until len) append(b, Array.get(o, i), delim)
            } else if (o is Iterable<*>) {
                for (p in o) append(b, p, delim)
            } else {
                b.append(delim).append(o)
            }
        }

        private fun statics() {
            abs(0)
            BigInteger.valueOf(0)
            Arrays.asList(arrayOfNulls<Any>(0))
            Collections.reverseOrder()
        }

        init {
            statics()
        }
    }
}

